(()=>{if(!new URLSearchParams(location.search).has('preview')&&'serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{document.documentElement.dataset.offlineReady='true'}).catch(()=>{document.documentElement.dataset.offlineReady='false'})}})();
